'use strict';
function accountDestination(){return principal?.kind==='employee'?'مسح البطاقة':principal?.kind==='admin'?'لوحة الإدارة':principal?.kind==='customer'?'بطاقتي':'لوحة التحكم';}
function openAccount(){publicPage='';role={owner:'owner',employee:'staff',admin:'admin',customer:'client'}[principal.kind];view=role==='staff'?'scan':role==='admin'?'accounts':'overview';history.replaceState(null,'',role==='admin'?'/admin':'/');render();}
const accountNav=publicNav;
publicNav=function(){if(!serverMode||!principal)return accountNav().replace(serverMode?/<button[^>]*data-action="demo-admin"[^>]*>.*?<\/button>/:'__never__','');return `<header class="public-nav"><button class="brand public-brand" data-action="home" aria-label="رجعة — الصفحة الرئيسية"></button><div class="actions"><button class="btn secondary" data-action="account-dashboard">${accountDestination()}</button><button class="btn quiet" data-action="server-logout">تسجيل الخروج</button></div></header>`;};
window.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='account-dashboard'||(b.dataset.action==='login'&&serverMode&&principal)){e.preventDefault();e.stopImmediatePropagation();openAccount();}else if(b.dataset.action==='home'){history.replaceState(null,'','/');}},true);
const experienceRender=render;
render=function(){experienceRender();if(serverMode&&principal&&publicPage==='home'){document.querySelectorAll('[data-action=login]').forEach(b=>{b.dataset.action='account-dashboard';b.textContent=accountDestination();});}if(!publicPage&&principal){const bar=document.querySelector('.topbar');if(bar&&!bar.querySelector('[data-action=home]'))bar.insertAdjacentHTML('afterbegin','<button class="btn quiet small" data-action="home">الصفحة الرئيسية</button>');}const auth=document.querySelector('.auth-layout');if(auth){document.body.classList.add('neon-auth');if(!document.querySelector('.public-nav'))auth.insertAdjacentHTML('beforebegin',publicNav());document.querySelectorAll('.public-brand').forEach(b=>b.innerHTML='<span class="ocean-brand-lockup"><img class="rijaa-brand-logo" src="/brand-logo.png" alt="رجعة — نظام الولاء"><img class="rijaa-brand-logo brand-white-word" src="/brand-logo.png" alt="" aria-hidden="true"></span>');auth.querySelector('.notice')?.remove();auth.querySelector('.brand')?.remove();auth.querySelector('section:first-child').insertAdjacentHTML('beforeend','<div class="auth-feature-list"><span>✦ هوية نشاطك، بكل تفاصيلها</span><span>▣ بطاقاتك وفريقك في مكان واحد</span><span>↗ كل زيارة تقرّب عميلك للمكافأة</span></div>');auth.querySelectorAll('input[type=password]').forEach((input,i)=>{input.id=input.id||'auth-password-'+i;input.closest('label').insertAdjacentHTML('beforeend',`<button type="button" class="password-toggle" data-action="toggle-password-visibility" data-target="${input.id}" aria-controls="${input.id}" aria-pressed="false">إظهار كلمة المرور</button>`);});auth.querySelectorAll('.btn.primary').forEach(b=>{if(b.querySelector('.glow-orbit'))return;const label=b.textContent;b.classList.add('glow-button');b.innerHTML=`<span class="glow-orbit" aria-hidden="true"><span>↗</span></span><span class="glow-label">${esc(label)}</span>`;});}else document.body.classList.remove('neon-auth');};
document.addEventListener('pointermove',e=>{if(!document.body.classList.contains('neon-auth'))return;document.body.style.setProperty('--neon-x',`${Math.round(e.clientX/innerWidth*100)}%`);document.body.style.setProperty('--neon-y',`${Math.round(e.clientY/innerHeight*100)}%`);},{passive:true});
render();

window.addEventListener('click',e=>{const b=e.target.closest('[data-action=toggle-password-visibility]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const input=document.getElementById(b.dataset.target);if(!input)return;const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'إخفاء كلمة المرور':'إظهار كلمة المرور';b.setAttribute('aria-pressed',String(show));},true);
